        this.groupsById.clear()
        this.nodesById.clear()
        this.activationIds = EMPTY_IDS
        this.fragmentIds = EMPTY_IDS
        this.edgeIds = EMPTY_IDS
        // Derived geometry reads model data and never writes it, so the session's read boundary is safe to narrow here.
        const diagram = this.editSession.getEditableDiagram() as DiagramData | null
        this.diagram = diagram
        if (!diagram) {
            this.surface = { height: 0, originX: 0, originY: 0, width: 0 }
            this.dispatchEvent(new Event(diagramGeometryMembershipChangedEvent('activation')))
            this.dispatchEvent(new Event(diagramGeometryMembershipChangedEvent('fragment')))
            this.dispatchEvent(new Event(GEOMETRY_SESSION_EVENT))

            return
        }

        const positioned = layout(diagram)
        for (const node of positioned.nodes) this.nodesById.set(node.id, node)
        for (const edge of positioned.edges) this.edgesById.set(edge.id, edge)
        for (const group of positioned.groups) this.groupsById.set(group.id, group)
        for (const activation of positioned.activations) this.activationsById.set(activation.id, activation)
        for (const fragment of positioned.fragments) this.fragmentsById.set(fragment.id, fragment)
        this.activationIds = Object.freeze(positioned.activations.map(({ id }) => id))
        this.edgeIds = Object.freeze(positioned.edges.map(({ id }) => id))
        this.fragmentIds = Object.freeze(positioned.fragments.map(({ id }) => id))
        this.surface = { height: positioned.height, originX: positioned.originX, originY: positioned.originY, width: positioned.width }
        this.subscribeDiagramObjects()
        this.dispatchEvent(new Event(diagramGeometryMembershipChangedEvent('activation')))
        this.dispatchEvent(new Event(diagramGeometryMembershipChangedEvent('fragment')))
        this.dispatchEvent(new Event(GEOMETRY_SESSION_EVENT))
    }

    private subscribeDiagramObjects() {
        const diagram = this.requireDiagram()
        for (const node of diagram.nodes) this.subscribeNode(node)
        for (const edge of diagram.edges) this.subscribeEdge(edge)
        for (const group of diagram.groups) this.subscribeGroup(group)
        for (const fragment of diagram.fragments ?? []) this.subscribeFragment(fragment)
        this.dispatchEvent(new Event(diagramGeometryFieldChangedEvent('fragment', fragment.id, 'guardPositions')))
    }

    /**
     * Measures the surface from the positioned objects the service already owns and assigns `width` and `height`
     * only when they actually change, so an edit inside the current bounds notifies nothing.
     */
    private refreshSurface() {
        const measured = surfaceSize(
            [...this.nodesById.values()],
            [...this.edgesById.values()],
            [...this.groupsById.values()],
            [...this.fragmentsById.values()],
            [...this.activationsById.values()],
        )
        const diagram = this.requireDiagram()
        const rootModel = diagram.meta.type === 'mindmap'
            ? diagram.nodes.find(({ kind }) => kind === 'root') : undefined
        const root = rootModel && rootModel.x === undefined && rootModel.y === undefined
            ? this.nodesById.get(rootModel.id) : undefined
        const originX = Math.max(this.surface.originX, measured.originX)
        const originY = Math.max(this.surface.originY, measured.originY)
        const height = Math.max(
            measured.height + originY - measured.originY,
            originY > this.surface.originY ? this.surface.height + originY - this.surface.originY : 0,
            root ? (root.y + root.height / 2) * 2 + originY : 0,
        )
        const width = Math.max(
            measured.width + originX - measured.originX,
            originX > this.surface.originX ? this.surface.width + originX - this.surface.originX : 0,
            root ? (root.x + root.width / 2) * 2 + originX : 0,
        )
        if (originX !== this.surface.originX) {
            this.surface.originX = originX
            this.dispatchEvent(new Event(diagramGeometryFieldChangedEvent('surface', SURFACE_ID, 'originX')))
        }
        if (originY !== this.surface.originY) {
            this.surface.originY = originY
            this.dispatchEvent(new Event(diagramGeometryFieldChangedEvent('surface', SURFACE_ID, 'originY')))
        }
        if (height !== this.surface.height) {
            this.surface.height = height
            this.dispatchEvent(new Event(diagramGeometryFieldChangedEvent('surface', SURFACE_ID, 'height')))
        }
        if (width === this.surface.width) return

        this.surface.width = width
        this.dispatchEvent(new Event(diagramGeometryFieldChangedEvent('surface', SURFACE_ID, 'width')))
    }

    private readonly handleNodeMembershipChanged = () => {
        const diagram = this.requireDiagram()
        const modelIds = new Set(diagram.nodes.map(({ id }) => id))
        for (const nodeId of [...this.nodesById.keys()]) {
            if (!modelIds.has(nodeId)) this.removeNodeGeometry(nodeId)
        }

export function DiagramZoomViewport({
    details = diagramObjectDetailsService,
    drawing = diagramEdgeDrawingService,
    emphasis = diagramEmphasisService,
    geometry = diagramGeometryService,
    groupDrawing = diagramGroupDrawingService,
    movement = diagramMoveService,
    placement = diagramNodePlacementService,
    resize = diagramResizeService,
    review = diagramChangeReviewService,
    selection = diagramSelectionService,
    session = diagramEditSessionService,
    viewService = diagramViewService,
}: DiagramZoomViewportProps) {
    const scrollerRef = useRef<HTMLDivElement>(null)
    const zoomSurfaceRef = useRef<HTMLDivElement>(null)
    const activePointerIdRef = useRef<number | null>(null)
    const lastPointerClientRef = useRef<{ x: number, y: number } | null>(null)
    const activePointerGestureRef = useRef<'group' | 'move' | 'pan' | 'placement' | 'resize' | null>(null)
    const completingGestureRef = useRef(false)
    const suppressClickRef = useRef(false)
    const scale = useSyncExternalStore(
        session.subscribeViewportScale,
        session.getViewportScaleSnapshot,
        session.getViewportScaleSnapshot,
    )
    const originX = useDiagramSurfaceField('originX', geometry)
    const originY = useDiagramSurfaceField('originY', geometry)
    const previousOriginRef = useRef<{ x: number, y: number } | null>(null)
    useLayoutEffect(() => {
        const previous = previousOriginRef.current
        const scroller = scrollerRef.current
        if (previous && scroller) {
            scroller.scrollLeft += (originX - previous.x) * scale
            scroller.scrollTop += (originY - previous.y) * scale
        }
        previousOriginRef.current = { x: originX, y: originY }
    }, [originX, originY, scale])
    useDiagramCtrlWheelZoom(scrollerRef, session)
    const panToolActive = useActiveDiagramTool(session, 'pan')
    const canStartPan = useCallback(() => session.getActiveToolSnapshot() === 'pan', [session])
    const beginPanGesture = useCallback(() => session.beginTransientGesture('pan'), [session])
    const completePanGesture = useCallback(() => session.completeTransientGesture(), [session])
    const pan = useDiagramSurfacePan(scrollerRef, {
        canStartPan,
        enabled: panToolActive,
        onPanCancel: completePanGesture,
        onPanComplete: completePanGesture,
        onPanStart: beginPanGesture,
        preventDefaultForTouch: true,
    })
    const endPanGesture = useCallback(() => {
        activePointerGestureRef.current = null
        activePointerIdRef.current = null
    }, [])

    const pointerDiagramPoint = useCallback((clientX: number, clientY: number) => {
        const zoomSurface = zoomSurfaceRef.current
        if (!zoomSurface) throw new Error('Diagram move viewport is unavailable')
        const drawingSurface = zoomSurface.querySelector<HTMLElement>('[aria-label="New diagram"]')
        if (!drawingSurface) throw new Error('Diagram drawing surface is unavailable')

        return convertClientToDiagramCoordinates(
            { clientX, clientY },
            {
                bounds: drawingSurface.getBoundingClientRect(),
                originX: geometry.getSurfaceFieldSnapshot('originX'),
                originY: geometry.getSurfaceFieldSnapshot('originY'),
                scrollLeft: 0,
                scrollTop: 0,
            },
            session.getViewportScaleSnapshot(),
        ).diagramPoint
    }, [geometry, session])

    const releaseActivePointer = useCallback(() => {
        const pointerId = activePointerIdRef.current
        activePointerIdRef.current = null
        if (pointerId === null) return

        scrollerRef.current?.releasePointerCapture?.(pointerId)
    }, [])

    const cancelActiveGestureForPinch = useCallback(() => {
        const gesture = activePointerGestureRef.current
        if (gesture === 'pan') pan.cancelPan()
        else if (gesture === 'placement') placement.cancelPlacement()
        else if (gesture === 'group') groupDrawing.cancelDrawing()
        else if (gesture === 'resize') resize.cancelResize()
        else if (gesture === 'move') movement.cancelMove()
        if (drawing.isDrawingActive()) drawing.cancelDrawing()
        if (placement.isPlacementActive()) placement.cancelPlacement()
        selection.cancelRectangleSelection()
        activePointerGestureRef.current = null
        releaseActivePointer()
        suppressClickRef.current = true
    }, [drawing, groupDrawing, movement, pan, placement, releaseActivePointer, resize, selection])
    const pinch = useDiagramPinchZoom(scrollerRef, session, cancelActiveGestureForPinch)
    const handlePinchPointerDownCapture = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
        if (event.currentTarget.contains(event.target as Node)) pinch.handlePointerDownCapture(event)
    }, [pinch])
    const handlePinchPointerMoveCapture = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
        if (event.currentTarget.contains(event.target as Node)) pinch.handlePointerMoveCapture(event)
    }, [pinch])
    usePreserveDiagramZoomCenter(scrollerRef, scale, pinch.anchorRef)

    const handlePointerDown = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
        if (!event.currentTarget.contains(event.target as Node)) return
        if (activePointerIdRef.current !== null || event.button !== 0 || event.isPrimary === false) return
        if (session.getActiveToolSnapshot() === 'pan') {
            if (!pan.beginPan(event)) return
        activePointerGestureRef.current = null
        releaseActivePointer()
    }, [endPanGesture, pan, releaseActivePointer, session])

    useEffect(() => {
        window.addEventListener('keydown', handleWindowKeyDown)

        return () => window.removeEventListener('keydown', handleWindowKeyDown)
    }, [handleWindowKeyDown])

    useEffect(
        () => session.subscribeTransientGesture(handleTransientGestureChanged),
        [handleTransientGestureChanged, session],
    )

    return (
        <Box
            aria-label="New diagram scroller"
            onClickCapture={handleClickCapture}
            onKeyDown={handleKeyDown}
            onLostPointerCapture={handleLostPointerCapture}
            onPointerCancelCapture={handlePointerCancelCapture}
            onPointerCancel={handlePointerCancel}
            onPointerDownCapture={handlePinchPointerDownCapture}
            onPointerDown={handlePointerDown}
            onPointerMoveCapture={handlePinchPointerMoveCapture}
            onPointerMove={handlePointerMove}
            onPointerUpCapture={handlePointerUpCapture}
            onPointerUp={handlePointerUp}
            onScroll={handleScroll}
            ref={scrollerRef}
            sx={{ flex: 1, minHeight: 0, minWidth: 0, overflow: 'auto', px: 2, pb: 2, pt: 7, touchAction: panToolActive ? 'none' : 'pan-x pan-y' }}
        >
            <Box data-testid="new-diagram-zoom-surface" ref={zoomSurfaceRef} sx={{ transformOrigin: 'top left', zoom: scale }}>
                <NewDiagram
                    details={details}
                    drawing={drawing}
                    emphasis={emphasis}
                    geometry={geometry}
                    groupDrawing={groupDrawing}
                    placement={placement}
                    review={review}
                    selection={selection}
                    session={session}
                    viewService={viewService}
                />
            </Box>
        </Box>
    )
}

